-- undo LOOT1A (V1 or V2)
DELETE FROM `creature_loot_template` WHERE `Comment` LIKE 'LOOT1A %';
UPDATE `creature_template` SET `mingold` = 0, `maxgold` = 0 WHERE `entry` IN (150228, 150229, 150238, 151091, 152843, 153239, 153266, 153581, 153582, 153583, 153964, 156814, 156900, 157300, 160394, 160433, 161130, 161131, 161133, 162817, 165150, 9159801, 9159802, 9159803);
UPDATE `creature_template` t SET t.`lootid` = 0 WHERE t.`entry` IN (150228, 150229, 150238, 151091, 152843, 153239, 153266, 153581, 153582, 153583, 153964, 156814, 156900, 157300, 160394, 160433, 161130, 161131, 161133, 162817, 165150, 9159801, 9159802, 9159803) AND NOT EXISTS (SELECT 1 FROM `creature_loot_template` l WHERE l.`Entry` = t.`entry`);
